SELECT 100.0 * SUM(CASE WHEN cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL THEN 1 ELSE 0 END) / SUM(CASE WHEN s.name = 'Coldsnap' THEN 1 ELSE 0 END) AS percentage_incredibly_powerful_cards
FROM cards c
JOIN sets s ON c.setCode = s.code;

SELECT SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT
  100.0 * SUM(CASE WHEN SEX = 'F' AND CAST(strftime('%Y', Birthday) AS INTEGER) > 1930 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN SEX = 'F' THEN 1 ELSE 0 END), 0) AS percentage
FROM Patient;
